"""สร้าง db/73_exam_isomer.sql — ข้อสอบหัวข้อไอโซเมอร์ (โครงสร้าง + สเตอริโอ) ใช้รูปจาก web/assets/exam/isomer"""
import json, os
P = "assets/exam/isomer/"
I = lambda n: P + n + ".png"
T = "ไอโซเมอร์"
Q = []
def add(kind, q, data, pts, ex, img=None, eximg=None): Q.append(dict(kind=kind, q=q, data=data, points=pts, explain=ex, img=img, explain_img=eximg))
def mc(q, ch, ans, ex, pts=1, img=None, eximg=None):
    add("mcq", q, {"choices": [({"t": c} if isinstance(c, str) else {"t": c[0], "img": c[1]}) for c in ch], "answer": ans}, pts, ex, img, eximg)
def tf(q, a, ex, pts=1, img=None): add("tf", q, {"answer": a}, pts, ex, img)

mc("แอลเคนสูตรโมเลกุล C4H10 มีไอโซเมอร์โครงสร้างกี่แบบ", ["1 แบบ", "2 แบบ", "3 แบบ", "4 แบบ"], 1, "C4H10 มี 2 แบบ คือ บิวเทน (โซ่ตรง) และ 2-เมทิลโพรเพน (โซ่กิ่ง)", eximg=I("p_chain"))
mc("แอลเคนสูตรโมเลกุล C5H12 มีไอโซเมอร์โครงสร้างกี่แบบ", ["2 แบบ", "3 แบบ", "4 แบบ", "5 แบบ"], 1, "C5H12 มี 3 แบบ: เพนเทน, 2-เมทิลบิวเทน และ 2,2-ไดเมทิลโพรเพน", eximg=I("pentane"))
mc("สารคู่ในรูปเป็นไอโซเมอร์โครงสร้างชนิดใด", ["โซ่คาร์บอน", "ตำแหน่งหมู่ฟังก์ชัน", "หมู่ฟังก์ชัน", "เรขาคณิต (cis-trans)"], 1, "1-โพรพานอลและ 2-โพรพานอล มีหมู่ -OH เหมือนกันแต่ติดคนละตำแหน่ง จึงเป็นไอโซเมอร์ตำแหน่ง", img=I("p_pos"))
mc("เอทานอล (CH3CH2OH) กับไดเมทิลอีเทอร์ (CH3OCH3) เป็นไอโซเมอร์ชนิดใด", ["โซ่คาร์บอน", "ตำแหน่งหมู่ฟังก์ชัน", "หมู่ฟังก์ชัน", "เรขาคณิต (cis-trans)"], 2, "สูตรโมเลกุลเดียวกัน (C2H6O) แต่มีหมู่ฟังก์ชันต่างกัน (แอลกอฮอล์ vs อีเทอร์)", img=I("p_func"))
mc("บิวเทนกับ 2-เมทิลโพรเพน (ในรูป) เป็นไอโซเมอร์ชนิดใด", ["โซ่คาร์บอน", "ตำแหน่งหมู่ฟังก์ชัน", "หมู่ฟังก์ชัน", "เรขาคณิต (cis-trans)"], 0, "ต่างกันที่การจัดเรียงโซ่คาร์บอน (โซ่ตรง vs โซ่กิ่ง)", img=I("p_chain"))
mc("สารในข้อใดแสดงไอโซเมอร์เรขาคณิต (cis-trans) ได้", [("", I("propene")), ("", I("isobutene")), ("", I("cis2butene")), ("", I("11dce"))], 2, "ต้องมี C=C ที่คาร์บอนแต่ละตัวต่อกับหมู่ที่ต่างกัน 2 หมู่ — บิวต์-2-อีนตรงเงื่อนไข ส่วนโพรพีน, 2-เมทิลโพรพีน และ 1,1-ไดคลอโรเอทีน มีคาร์บอนข้างหนึ่งต่อกับหมู่เหมือนกัน")
mc("สารในข้อใดมีคาร์บอนไครัล (chiral carbon)", [("", I("ethanol")), ("", I("2propanol")), ("", I("2butanol")), ("", I("3pentanol"))], 2, "C2 ของ 2-บิวทานอลต่อกับ 4 หมู่ต่างกัน: -OH, -H, -CH3, -CH2CH3")
mc("สารสูตร C4H8 มีไอโซเมอร์โครงสร้าง (นับรวมโครงสร้างวงแหวน แต่ไม่นับ cis-trans) กี่แบบ", ["3 แบบ", "4 แบบ", "5 แบบ", "6 แบบ"], 2, "บิวต์-1-อีน, บิวต์-2-อีน, 2-เมทิลโพรพีน, ไซโคลบิวเทน, เมทิลไซโคลโพรเพน = 5 แบบ (ถ้านับ cis/trans แยก จะเป็น 6 สเตอริโอไอโซเมอร์)", 2)
mc("สารสูตร C4H10O มีไอโซเมอร์โครงสร้างกี่แบบ (แอลกอฮอล์ + อีเทอร์)", ["4 แบบ", "5 แบบ", "6 แบบ", "7 แบบ"], 3, "แอลกอฮอล์ 4 แบบ (บิวทัน-1-ออล, บิวทัน-2-ออล, 2-เมทิลโพรพัน-1-ออล, 2-เมทิลโพรพัน-2-ออล) + อีเทอร์ 3 แบบ (ไดเอทิลอีเทอร์, เมทิลโพรพิลอีเทอร์, ไอโซโพรพิลเมทิลอีเทอร์) = 7", 2)
mc("ข้อใดกล่าวถูกต้องเกี่ยวกับเอนันทิโอเมอร์ (enantiomer) คู่หนึ่ง", ["จุดเดือดต่างกันมาก", "หมุนระนาบแสงโพลาไรซ์ในทิศตรงข้ามกัน องศาเท่ากัน", "เป็นโครงสร้างเดียวกัน ซ้อนทับกันได้", "ไม่มีคาร์บอนไครัลเลย"], 1, "เอนันทิโอเมอร์เป็นภาพสะท้อนในกระจกที่ซ้อนทับกันไม่ได้ สมบัติทางกายภาพส่วนใหญ่เหมือนกัน แต่หมุนแสงโพลาไรซ์ตรงข้ามกัน", img=I("p_enan"))
mc("เงื่อนไขของ C=C ที่ทำให้เกิดไอโซเมอร์เรขาคณิตคือข้อใด", ["คาร์บอนตัวใดตัวหนึ่งของ C=C ต่อกับหมู่เหมือนกัน 2 หมู่", "คาร์บอนแต่ละตัวของ C=C ต่อกับหมู่ที่ต่างกัน 2 หมู่", "ต้องมีธาตุเฮไลด์อยู่ในโมเลกุล", "ต้องเป็นโมเลกุลวงแหวนเท่านั้น"], 1, "พันธะคู่หมุนอิสระไม่ได้ ถ้าแต่ละ C ต่อกับหมู่ต่างกัน 2 หมู่จะเกิดรูป cis และ trans")
mc("สารที่มีคาร์บอนไครัลต่างกัน 2 อะตอม (เช่น 2,3-ไดโบรโมเพนเทน) มีสเตอริโอไอโซเมอร์ได้สูงสุดกี่แบบ", ["2 แบบ", "3 แบบ", "4 แบบ", "8 แบบ"], 2, "จำนวนสเตอริโอไอโซเมอร์สูงสุด = 2ⁿ เมื่อ n = จำนวนคาร์บอนไครัล → 2² = 4", 2, img=I("23dbp"))

tf("บิวเทนและ 2-เมทิลโพรเพนเป็นไอโซเมอร์กัน", True, "สูตรโมเลกุลเดียวกัน (C4H10) แต่โครงสร้างต่างกัน")
tf("เอทานอลและไดเมทิลอีเทอร์มีสมบัติทางกายภาพ (เช่น จุดเดือด) เหมือนกัน เพราะสูตรโมเลกุลเดียวกัน", False, "หมู่ฟังก์ชันต่างกัน: เอทานอลมีพันธะไฮโดรเจนระหว่างโมเลกุล จุดเดือดสูงกว่าไดเมทิลอีเทอร์มาก")
tf("โมเลกุลที่มีคาร์บอนไครัล 1 อะตอม จะมีเอนันทิโอเมอร์ (ภาพสะท้อนในกระจกที่ซ้อนทับไม่ได้) เสมอ", True, "คาร์บอนไครัลเดียวทำให้โมเลกุลไม่มีระนาบสมมาตร จึงมีคู่เอนันทิโอเมอร์เสมอ")
tf("1,1-ไดคลอโรเอทีนมีไอโซเมอร์เรขาคณิต (cis-trans)", False, "คาร์บอนตัวหนึ่งต่อกับ Cl เหมือนกัน 2 อะตอม จึงไม่เกิด cis-trans", img=I("11dce"))

