def lit(s): return "$j$" + (s if isinstance(s, str) else json.dumps(s, ensure_ascii=False)) + "$j$"
out = ["-- 73: ข้อสอบหัวข้อ “ไอโซเมอร์” (โครงสร้าง + สเตอริโอ) — ต้องรัน 72 ก่อน · รันซ้ำได้ (ไม่เพิ่มข้อซ้ำ)",
       "-- รูปโครงสร้างอยู่ที่ assets/exam/isomer/ (สร้างด้วย tools/make_isomer_imgs.py)", ""]
for q in Q:
    out.append(f"""insert into exam_questions (topic, kind, q, img, data, points, explain, explain_img)
select {lit(T)}::text, {lit(q['kind'])}, {lit(q['q'])}, {lit(q['img']) if q['img'] else 'null'}, {lit(q['data'])}::jsonb, {q['points']}, {lit(q['explain'])}, {lit(q['explain_img']) if q['explain_img'] else 'null'}
where not exists (select 1 from exam_questions where topic = {lit(T)} and q = {lit(q['q'])});
""")
out.append(f"""-- ชุดสอบฉบับร่าง (ยังไม่ระบุห้อง): เปิดแท็บ 📝 ข้อสอบ → แก้ → เลือกห้อง/เวลา → เปลี่ยนสถานะเป็น “เปิดให้สอบ”
with e as (
  insert into exams (title, topic, minutes, shuffle, max_attempts, show_result, max_score, status)
  select 'สอบเก็บคะแนน: ไอโซเมอร์ (โครงสร้าง + สเตอริโอ)', {lit(T)}, 40, true, 1, 'after_close', 10, 'draft'
  where not exists (select 1 from exams where title = 'สอบเก็บคะแนน: ไอโซเมอร์ (โครงสร้าง + สเตอริโอ)')
  returning id)
insert into exam_items (exam_id, qid, pos)
select e.id, q.id, row_number() over (order by q.created_at, q.id) from e, exam_questions q where q.topic = {lit(T)};
""")
open("db/73_exam_isomer.sql", "w").write("\n".join(out))
print(len(Q), "questions;", sum(q['points'] for q in Q), "points")
